package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.io.*;import org.json.*;
public class MediaDeletionTest {
 static final String ROOT="/Media/Movies";
 static final class Files implements MediaDeletion.Source,MediaDeletion.Delete {
  final Map<String,NasClient.Entry> rows=new LinkedHashMap<>();final List<List<String>> deletes=new ArrayList<>();
  Files(String... files){for(String p:files){rows.put(p,new NasClient.Entry(MediaDeletion.name(p),p,false,10));String d=MediaDeletion.parent(p);while(!d.equals("/")){rows.putIfAbsent(d,new NasClient.Entry(MediaDeletion.name(d),d,true,0));d=MediaDeletion.parent(d);}}for(NasClient.Entry e:rows.values())e.realPath="/volume1"+e.path;}
  public List<NasClient.Entry> list(String p)throws Exception{if(!p.isEmpty()&&(!rows.containsKey(p)||!rows.get(p).directory))throw new IOException("missing fixture folder");List<NasClient.Entry> out=new ArrayList<>();for(NasClient.Entry original:rows.values())if(MediaDeletion.parent(original.path).equals(p.isEmpty()?"/":p)){NasClient.Entry e=new NasClient.Entry(original.name,original.path,original.directory,original.size);e.modified=original.modified;e.realPath=original.realPath;e.symbolic=original.symbolic;out.add(e);}return out;}
  public void paths(List<String> paths)throws Exception{deletes.add(List.copyOf(paths));for(String p:paths){assertNotEquals(ROOT,p);assertNotEquals("/Media",p);NasClient.Entry e=rows.get(p);assertNotNull(e);if(e.directory)assertTrue("Never delete a nonempty directory",list(p).isEmpty());rows.remove(p);}}
 }
 MediaDeletion movie(Files fs,String p)throws Exception{return new MediaDeletion(List.of(p),List.of(ROOT),true,fs,List.of());}
 @Test public void entireMovieAndAuxiliaryFilesLeaveNoEmptyFolder()throws Exception{String p=ROOT+"/Movie/Disc1/Movie.mkv";Files fs=new Files(p,ROOT+"/Movie/release.nfo",ROOT+"/Movie/Subs/Movie.hu.srt",ROOT+"/Movie/Sample/sample.mkv");fs.rows.put(ROOT+"/Movie/Empty",new NasClient.Entry("Empty",ROOT+"/Movie/Empty",true,0));fs.rows.get(ROOT+"/Movie/Empty").realPath="/volume1"+ROOT+"/Movie/Empty";MediaDeletion inventory=movie(fs,p);MediaDeletion.Plan plan=inventory.plan(null);assertEquals(4,plan.files.size());inventory.execute(plan,fs);assertFalse(fs.rows.containsKey(ROOT+"/Movie"));assertTrue(fs.rows.containsKey(ROOT));}
 @Test public void sharedFolderKeepsOtherMovieAndItsNfo()throws Exception{String a=ROOT+"/A.mkv",b=ROOT+"/B.mkv";Files fs=new Files(a,b,ROOT+"/A.nfo",ROOT+"/B.nfo",ROOT+"/library.nfo");MediaDeletion inv=movie(fs,a);assertEquals(Set.of(a,ROOT+"/A.nfo"),new HashSet<>(inv.plan(null).files));inv.execute(inv.plan(null),fs);assertTrue(fs.rows.containsKey(b));assertTrue(fs.rows.containsKey(ROOT+"/B.nfo"));assertTrue(fs.rows.containsKey(ROOT+"/library.nfo"));}
 Files series(){return new Files(ROOT+"/Show/Season 1/S01E01.mkv",ROOT+"/Show/Season 1/release.nfo",ROOT+"/Show/Season 2/S02E01.mkv",ROOT+"/Show/Season 2/release.nfo",ROOT+"/Show/tvshow.nfo");}
 MediaDeletion show(Files fs)throws Exception{return new MediaDeletion(List.of(ROOT+"/Show"),List.of(ROOT),false,fs,List.of());}
 @Test public void chooseOnlyOneSeasonKeepsOtherAndSharedNfo()throws Exception{Files fs=series();MediaDeletion inv=show(fs);assertEquals(Set.of(1,2),inv.seasons);inv.execute(inv.plan(Set.of(1)),fs);assertFalse(fs.rows.containsKey(ROOT+"/Show/Season 1"));assertTrue(fs.rows.containsKey(ROOT+"/Show/Season 2/S02E01.mkv"));assertTrue(fs.rows.containsKey(ROOT+"/Show/tvshow.nfo"));}
 @Test public void allSeasonsRemoveShowAndItsMetadata()throws Exception{Files fs=series();MediaDeletion inv=show(fs);MediaDeletion.Plan plan=inv.plan(Set.of(1,2));assertTrue(plan.allSeasons);inv.execute(plan,fs);assertFalse(fs.rows.containsKey(ROOT+"/Show"));}
 @Test public void mixedSeasonsAndExplicitSeasonSidecars()throws Exception{String d=ROOT+"/Show";Files fs=new Files(d+"/S01E01.mkv",d+"/S02E01.mkv",d+"/S01.nfo",d+"/S02.nfo",d+"/tvshow.nfo");MediaDeletion inv=show(fs);MediaDeletion.Plan plan=inv.plan(Set.of(1));assertTrue(plan.files.contains(d+"/S01.nfo"));assertFalse(plan.files.contains(d+"/S02.nfo"));inv.execute(plan,fs);assertTrue(fs.rows.containsKey(d+"/S02E01.mkv"));assertTrue(fs.rows.containsKey(d+"/tvshow.nfo"));}
 @Test public void mergedSeasonRootsCleanTheirSharedParent()throws Exception{Files fs=series();MediaDeletion inv=new MediaDeletion(List.of(ROOT+"/Show/Season 1",ROOT+"/Show/Season 2"),List.of(ROOT),false,fs,List.of());inv.execute(inv.plan(Set.of(1,2)),fs);assertFalse(fs.rows.containsKey(ROOT+"/Show"));}
 @Test public void changedContentStopsBeforeFirstDelete()throws Exception{String p=ROOT+"/Movie/Movie.mkv";Files fs=new Files(p);MediaDeletion inv=movie(fs,p);MediaDeletion.Plan plan=inv.plan(null);fs.rows.get(p).modified=2;try{inv.execute(plan,fs);fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("megváltozott"));}assertTrue(fs.deletes.isEmpty());}
 @Test public void uncertainDeleteIsNeverRetried()throws Exception{String p=ROOT+"/Movie/Movie.mkv";Files fs=new Files(p);MediaDeletion inv=movie(fs,p);int[] calls={0};try{inv.execute(inv.plan(null),paths->{calls[0]++;throw new IOException("uncertain");});fail();}catch(IOException expected){}assertEquals(1,calls[0]);}
 @Test public void unsafePathsAndLibraryRootAreRejected()throws Exception{for(String p:List.of("/Media/../Private/file.mkv","/Media//a.mkv","/Media/./a.mkv","https://nas/file","/Media/Movies\\a.mkv"))try{MediaDeletion.path(p);fail();}catch(IllegalArgumentException expected){}Files fs=series();try{new MediaDeletion(List.of(ROOT),List.of(ROOT),false,fs,List.of());fail();}catch(IOException expected){assertTrue(fs.deletes.isEmpty());}}
 @Test public void realPathEscapeAndSymlinkRejected()throws Exception{String p=ROOT+"/Movie/Movie.mkv";Files fs=new Files(p);fs.rows.get(ROOT+"/Movie").realPath="/volume1/Media/Movies/Movie";fs.rows.get(p).realPath="/volume1/Private/Movie.mkv";try{movie(fs,p);fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("hivatkozást"));}assertTrue(fs.deletes.isEmpty());}
 @Test public void removingMergedPrimaryRetargetsRemainingMembers()throws Exception{LocalEdits edits=new LocalEdits("{}");Library.Card a=new Library.Card("/Shows/A","A",false),b=new Library.Card("/Shows/B","B",false),c=new Library.Card("/Shows/C","C",false);edits.merge("lib",b,a);List<Library.Card> first=edits.apply(List.of(a,b,c),"lib");edits.merge("lib",c,first.stream().filter(x->x.path.equals(a.path)).findFirst().get());edits.deletedMedia(p->p.equals(a.path));List<Library.Card> result=edits.apply(List.of(b,c),"lib");assertEquals(1,result.size());assertEquals(b.path,result.get(0).path);}

 @Test public void companionBelongsToLongestMatchingVideoStem()throws Exception{String a=ROOT+"/Alien.mkv",b=ROOT+"/Alien.Resurrection.mkv",sub=ROOT+"/Alien.Resurrection.srt";Files fs=new Files(a,b,sub);assertFalse(movie(fs,a).plan(null).files.contains(sub));assertTrue(movie(fs,b).plan(null).files.contains(sub));}
 @Test public void languageCompanionAndSubsResolveInTheirActualVideoFolder()throws Exception{String a=ROOT+"/Movie.mkv",b=ROOT+"/Other.mkv",sub=ROOT+"/Subs/Movie.srt",wrong=ROOT+"/Elsewhere/Alien.mkv",orphan=ROOT+"/Subs/Unassigned.srt";Files fs=new Files(a,b,ROOT+"/Movie.en.srt",sub,wrong,orphan);MediaDeletion.Plan p=movie(fs,a).plan(null);assertTrue(p.files.contains(ROOT+"/Movie.en.srt"));assertTrue(p.files.contains(sub));assertFalse(p.files.contains(orphan));}

 @Test public void unknownFilesAreRetainedByDefaultAndOptInIsVerified()throws Exception{String p=ROOT+"/Movie/Movie.mkv",iso=ROOT+"/Movie/disc.iso",pdf=ROOT+"/Movie/notes.pdf";Files fs=new Files(p,iso,pdf);MediaDeletion inv=movie(fs,p);MediaDeletion.Plan safe=inv.plan(null);assertEquals(Set.of(iso,pdf),new HashSet<>(safe.unknown));assertEquals(List.of(p),safe.files);inv.execute(safe,fs);assertTrue(fs.rows.containsKey(iso));assertTrue(fs.rows.containsKey(ROOT+"/Movie"));Files opt=new Files(p,iso,pdf);MediaDeletion full=movie(opt,p);MediaDeletion.Plan approved=full.plan(null,true);assertTrue(approved.includeUnknown);assertTrue(approved.files.containsAll(approved.unknown));full.execute(approved,opt);assertFalse(opt.rows.containsKey(ROOT+"/Movie"));}
 @Test public void togglingUnknownsDoesNotChangeAuxiliaryCleanup()throws Exception{String p=ROOT+"/Movie/Movie.mkv";Files fs=new Files(p,ROOT+"/Movie/release.nfo");MediaDeletion inv=movie(fs,p);assertTrue(inv.plan(null).unknown.isEmpty());assertEquals(inv.plan(null).files,inv.plan(null,true).files);inv.execute(inv.plan(null),fs);assertFalse(fs.rows.containsKey(ROOT+"/Movie"));}

 @Test public void missingPhysicalFileOrDirectoryPathFailsClosed()throws Exception{String p=ROOT+"/Movie/Movie.mkv";for(String missing:List.of(p,ROOT+"/Movie")){Files fs=new Files(p);fs.rows.get(missing).realPath="";IOException error=assertThrows(IOException.class,()->movie(fs,p));assertTrue(error.getMessage().contains("fizikai útvonalat"));assertTrue(fs.deletes.isEmpty());}}

 @Test public void selectedRootCannotEscapeItsConfiguredLibraryPhysicalPath()throws Exception{String file=ROOT+"/Movie/Movie.mkv";Files fs=new Files(file);fs.rows.get(ROOT+"/Movie").realPath="/volume1/Private";fs.rows.get(file).realPath="/volume1/Private/Movie.mkv";IOException error=assertThrows(IOException.class,()->movie(fs,file));assertTrue(error.getMessage().contains("hivatkozást"));assertTrue(fs.deletes.isEmpty());}
 @Test public void sameFolderFileAliasIsAlsoRejected()throws Exception{String file=ROOT+"/Movie/Movie.mkv";Files fs=new Files(file);fs.rows.get(file).realPath="/volume1"+ROOT+"/Movie/Other.mkv";assertThrows(IOException.class,()->movie(fs,file));assertTrue(fs.deletes.isEmpty());}
}
